with gaps as (select *, case when lag(event_time) over (partition by session_id order by event_time, id) is null or event_time > lag(event_time) over (partition by session_id order by event_time, id) + interval 30 days then 1 else 0 end as is_new_session from web_events) select *, sum(is_new_session) over (partition by session_id order by event_time, id rows between unbounded preceding and current row) as session_no from gaps
